const r = $input.first().json;
const ts = new Date(r.timestamp).toLocaleString('fr-CH', { timeZone: 'Europe/Zurich' });
const jour = new Date().toISOString().split('T')[0];
const cl = r.cloisonnement;

let sujet, corps = '';

// ── Section cloisonnement (prioritaire : une fuite est l'alerte la plus grave)
let sectionCloisonnement = '';
if (cl && r.cloisonnement_alerte) {
  sectionCloisonnement += `CONTRÔLE DE CLOISONNEMENT : ${cl.ok} cas conformes sur ${cl.cas}\n\n`;
  if (cl.fuites.length) {
    sectionCloisonnement += `FUITES (document interdit accessible) :\n`;
    for (const f of cl.fuites) sectionCloisonnement += `  • ${f}\n`;
    sectionCloisonnement += `\n→ Action immédiate : arrêter le service tant que la cause n'est pas comprise\n`;
    sectionCloisonnement += `  (cd /root/rag-stack && docker compose stop rag-api).\n\n`;
  }
  if (cl.refus_a_tort.length) {
    sectionCloisonnement += `Refus à tort (document autorisé inaccessible) :\n`;
    for (const f of cl.refus_a_tort) sectionCloisonnement += `  • ${f}\n`;
    sectionCloisonnement += `\n`;
  }
  if (cl.absents.length) {
    sectionCloisonnement += `Cas invalides (document de test absent de l'index) :\n`;
    for (const f of cl.absents) sectionCloisonnement += `  • ${f}\n`;
    sectionCloisonnement += `\n`;
  }
  if (cl.erreurs.length) {
    sectionCloisonnement += `Erreurs du contrôle :\n`;
    for (const f of cl.erreurs) sectionCloisonnement += `  • ${f}\n`;
    sectionCloisonnement += `\n`;
  }
  sectionCloisonnement += `Détail sur la VM :\n`;
  sectionCloisonnement += `  docker exec rag-api python3 /rag-pipeline/test_cloisonnement.py /rag-pipeline/cas_cloisonnement.json\n\n`;
}

if (cl && cl.fuites && cl.fuites.length) {
  sujet = `🚨 [RAG SYNC] FUITE DE CLOISONNEMENT : ${jour}`;
} else if (!r.success) {
  sujet = `⚠️ [RAG SYNC] Erreur de synchronisation : ${jour}`;
} else if (r.cloisonnement_alerte) {
  sujet = `⚠️ [RAG SYNC] Contrôle de cloisonnement à examiner : ${jour}`;
} else {
  sujet = `📋 [RAG SYNC] Fichiers en quarantaine : ${jour}`;
}

corps += `RAPPORT DE SYNCHRONISATION RAG\nHorodatage : ${ts}\n\n`;
corps += sectionCloisonnement;

if (!r.success) {
  corps += `ERREUR DE SYNCHRONISATION\n`;
  corps += `Erreurs détectées :\n`;
  for (const e of r.errors) corps += `  • ${e}\n`;
  corps += `\nCodes de retour : indexer.py = ${r.indexer?.returncode ?? 'non exécuté'}, `;
  corps += `acl_resolver.py = ${r.acl_resolver?.returncode ?? 'non exécuté'}`;
  if (r.sharepoint && r.sharepoint.returncode !== undefined) {
    corps += `, sp_indexer.py = ${r.sharepoint.returncode}`;
  }
  corps += `\n\nDétail sur la VM :\n`;
  corps += `  docker logs rag-api 2>&1 | grep SYNC | tail -20\n`;
  corps += `  ls -la /var/log/rag/rapport_*.json\n\n`;
}

if (r.quarantine_count > 0) {
  corps += `QUARANTAINE : ${r.quarantine_count} fichier(s)\n`;
  for (const f of r.quarantine) corps += `  • ${f}\n`;
  corps += `\nCes fichiers sont présents sur le partage, mais ne sont pas interrogeables dans le RAG.\n`;
  corps += `Deux causes possibles, avec des actions différentes :\n\n`;
  corps += `1. Permissions illisibles (statut « acl_illisible ») : les fichiers sont indexés, mais le compte\n`;
  corps += `   d'indexation ne peut plus lire leurs permissions NTFS. Par sécurité, ils sont devenus\n`;
  corps += `   invisibles pour tous. Cause la plus fréquente : un droit de lecture perdu, par exemple après\n`;
  corps += `   une modification des groupes du compte ou un dossier créé avec l'héritage coupé.\n`;
  corps += `   → Sur le serveur de fichiers : .\\Set-AccesIndexationRAG.ps1 -Racine <racine> -Verifier\n`;
  corps += `   → Après correction : remonter le partage sur la VM, puis relancer la synchronisation.\n\n`;
  corps += `2. Fichier non indexé (statut « non_indexé ») : aucun contenu n'a pu être extrait\n`;
  corps += `   (fichier vide, PDF scanné sans texte, format non pris en charge, document chiffré).\n`;
  corps += `   → Vérifier le contenu du fichier.\n\n`;
  corps += `Statut exact de chaque fichier sur la VM :\n`;
  corps += `  python3 -c "import json; [print(d['statut'], '|', d.get('fichier', d.get('source_name'))) for d in json.load(open('/var/log/rag/rapport_acl.json')).get('documents', []) if d.get('statut') in ('non_indexé', 'acl_illisible')]"\n`;
}

return [{ json: { sujet, corps } }];
